// ============================================================
// Tc2_Utilities.F_UDINT 演示程序（FUNCTION，返回 T_Arg）
// ============================================================
// 场景：把 UDINT 业务量打包为 T_Arg，供下游 EventLogger / FormatString2
//       / ADS 消息的可变参数机制使用。
// 价值：替代手填 T_Arg 三字段（eType/cbLen/pData），一行调用搞定。
// 验证：在线写 nCycleCount 为示例值，bPackArg := TRUE；
//       下一周期 argDescriptor.cbLen = SIZEOF(UDINT)，argDescriptor.pData <> 0。
// ============================================================

IF bPackArg THEN
    // 单次完整调用：返回的 T_Arg 立即可喂给 F_PutInArg(arg := argDescriptor, ...)
    argDescriptor := F_UDINT(nCycleCount);
    bPackArg := FALSE;
END_IF;
